space {
  id = "grudge_hall",
  region = "far_enough",
  name = "The Hall of Grievances",
  description = "Shelves of stone ledgers to the roof, and clerks on ladders. A dwarf does not forget a wrong, and to be sure of it they are written down here, indexed, and reviewed. There is a counter for new entries. It has a queue, and a second counter for complaints about the first.",
  palette = { bg = "#0e0c0b", text = "#d2cabc", dim = "#70675c", accent = "#c8a468", border = "#463a2a" },

  things = {
    { name = "the Keeper of Grudges",
      key = "keeper",
      icon = "☺",
      description = "A clerk with a white beard in three plaits and a chisel behind his ear. Grudges are carved, not written. It makes you think first.",
      things = {
        { name = "his chisel", description = "Narrow, for lettering, with a handle worn to his grip. He has carved eleven thousand grievances with it and holds none of his own. He says the job cures you." },
        { name = "his three plaits", description = "One for grudges lodged, one for grudges upheld, one for grudges settled. The third plait is very short." },
        { name = "his spectacles", description = "Two lenses of clear crystal in an iron frame. He looks over them at people and through them at stone, and you have been looked over." },
      },
      actions = {
        { "Ask to see the oldest", say "He takes you to a slab by the door. It is against the mountain, for being heavy. It has been reviewed every century and upheld." },
        { "Look up the Longshift", when = no(flag "fe_knows_pebble"), set "fe_knows_pebble",
          say "He goes quiet, and brings down a thin ledger with one entry. It has no charge on it. A date, a level, and a name: {i}Pebble, apprentice{/}. \"There's no grudge,\" the Keeper says. \"Nobody could work out what he'd done wrong. He broke through. That's the job. It's what was on the other side that wasn't.\" He puts it back. \"He drinks at the Second Shift. He doesn't talk about it. Nobody asks.\"" },
        { "Ask what was lodged that day", when = all { flag "fe_knows_pebble", no(flag "fe_knows_unlodged") }, set "fe_knows_unlodged",
          say "\"Nothing,\" he says. Then, because a Keeper cannot leave a record wrong: \"Something. They brought a slab. The whole shift, carrying it between them. They stood at that counter for a day.\" He takes off his spectacles. \"Nobody could say who it was against. You can't carve a grudge with no name on it. So it's in the back. It isn't lodged. It isn't not.\" He moves a ladder aside. Behind the index there is a low door. \"You've been down there,\" he says. \"Go and see if you can do better than we did.\"" },
        { "Lodge a grudge", say "You think. There is the sergeant at the gate, the hermit, a goose. The Keeper waits with the chisel raised. You find, to your surprise, that none of it will go into stone. \"No,\" he says, lowering it. \"Mostly it won't. That's what the stone's for.\"" },
      } },
    { name = "the oldest grudge",
      description = "A slab by the door, taller than you, black with age. One line of runes, cut a hand deep. {i}Against the mountain. For being heavy.{/} Below it, nine smaller lines: one for each review. Each says {i}upheld{/}.",
      things = {
        { name = "the nine reviews", description = "A hundred years apart, to the day. At each one the Keeper of the time reads the charge aloud, to the roof, and allows the mountain a full shift to answer." },
        { name = "a chip in the corner", description = "Fresh, and swept up. The next review is due in forty years, and the present Keeper has started cutting the tenth line early, a stroke a year, on the assumption." },
      },
      actions = {
        { "Ask if the mountain ever answered", say "The clerks nearby stop chiselling. \"Once,\" the Keeper says. \"At the ninth. We don't keep it out front.\"" },
      } },
    { name = "the new entries",
      key = "new entries",
      description = "This shift's grudges, on a rack, awaiting the chisel.",
      things = {
        { name = "an entry, pending", visible_if = flag "rope_taken",
          description = "{i}A tall person. One rope, forty fathoms, from its peg at the Longshift. Coiled since, badly.{/} You read it twice. You adjust the rope on your shoulder so that it shows less." },
        { name = "an entry about a cart", visible_if = flag "cart_ridden",
          description = "{i}Person unknown. One ore cart, taken down the old rails without a docket. Brake not applied. See also: turnip.{/}" },
        { name = "an entry about soup", description = "{i}Against my brother, for saying our mother's soup was thin. Ninth renewal.{/}" },
        { name = "an entry about a ladder", description = "{i}Against Brun Tallow, of the fourth tier, for one ladder, borrowed in my grandfather's time and returned a rung short.{/} A clerk has pencilled beside it: {i}he says it was always that many. Count disputed. See forty other entries.{/}" },
        { name = "an entry about a look", description = "{i}Against my wife's cousin, for a look.{/} The clerk has asked, in the margin, which look, and has been given a small drawing." },
      } },
    { name = "the shelves",
      description = "Stone ledgers, each as thick as a doorstep, shelved to the roof by family and then by year. A dwarf can walk in and be handed, within a minute, everything anyone has held against their line since the founding.",
      things = {
        { name = "a ledger at eye level", description = "Your eye level, which puts it on the ninth shelf. It is one family's grievances against another over the placing of a lamp. It runs to six volumes and both families attend each other's weddings." },
        { name = "a clerk on a ladder", description = "Forty feet up, re-cutting a line that has worn shallow. A grudge that cannot be read is no grudge. It is slow work, and he hums the four-hundredth verse while he does it, as allowed." },
        { name = "the index", description = "A wall of small slate tiles on pegs, one per grudge, cross-hung by offender, by injured party and by subject. Under {i}Soup{/} there are nine hundred tiles." },
        { name = "a ledger with a ribbon", description = "Red ribbon means upheld on appeal. This one is against a clock, for striking during a funeral. The clock lost. It has been silent on that hour ever since, and you can go and hear it not strike." },
      } },
    { name = "the settled shelf",
      description = "One shelf, short, for grudges that were made up. There are four ledgers on it. They are shown to schoolchildren as a curiosity.",
      things = {
        { name = "the first settled grudge", description = "Two sisters, a shared pick. Settled after three hundred years when one of them said, at the other's bedside, {i}oh, keep it{/}. It is carved in full. The Keepers have never agreed on whether that counts as settled or as won." },
        { name = "the newest settled grudge", description = "Forty years old. A baker forgave a debt of one loaf. There was a procession." },
        { name = "a space on the shelf", description = "Kept clear and dusted, the width of one thin ledger. Nobody will say which they are hoping to put there." },
      } },
    { name = "the queue",
      description = "Dwarves with slips, waiting to lodge. They wait well. It is in the nature of a grudge that it will keep.",
      things = {
        { name = "the dwarf in front of you", description = "He is rehearsing under his breath. It is about a borrowed ladder, and it has verses." },
        { name = "a very young dwarf", description = "Thirty, perhaps, clutching a slip, lodging her first. It is against her brother, for telling. Her mother stands behind her with the face of someone at a naming day." },
        { name = "a dwarf with no slip", description = "He comes every day and stands in the queue and, at the counter, says that he has nothing at present. The clerks say he is lonely, and enter him as {i}nil{/}, and ask after his knee." },
      },
      actions = {
        { "Join it", say "You stand in the queue. It moves. It is the first queue you have met in this kingdom that does, at the rate of one grievance every quarter of an hour, exactly. You leave before the counter, having nothing, and the dwarf with no slip gives you a look of fellowship." },
      } },
    { name = "the complaints counter",
      description = "For grudges against the Hall. The clerk here keeps a ledger of grudges against the complaints counter. He will not say where that one's complaints go.",
      actions = {
        { "Ask where they go", say "He looks at you for some time. Then he reaches under the counter and brings out a small slate, with one tile on it, and writes you down." },
      } },
    { name = "the review bench",
      description = "Three stone seats under a lamp, where grudges come up every hundred years to be upheld, amended or, in theory, struck. The cushions were provided in the second century, after a grievance.",
      things = {
        { name = "the three reviewers", description = "Elders, in grey, reading a slab between them. They have been on this one since the start of the shift. It concerns a dog. There have been no dogs in Far Enough for four hundred years, and the grudge has outlived the animal, the owner and the breed." },
        { name = "the striking hammer", description = "For breaking the slab of a grudge found to be false. It hangs on the wall, under glass. It has never been used. A dwarf does not lodge what is not so." },
      } },
    { name = "the carving room",
      description = "Through an arch: twenty clerks at twenty slabs, with mallets, cutting the shift's entries. The sound is a steady small clicking, and under it the murmur of each one reading his line aloud before he commits it.",
      things = {
        { name = "a slab half cut", description = "{i}Against the tall person at the gate, for{/} and there it stops. The clerk has put down his mallet. He is waiting, he says, to see what you do." },
        { name = "the dust", description = "Fine, grey, ankle deep under every bench. It is swept at the end of the shift into sacks and taken to the Under-Fields. The mushrooms do well on it. Nobody examines that thought." },
      } },
    { name = "a low door behind the index",
      key = "low door",
      visible_if = flag "fe_knows_unlodged",
      description = "Three feet high, of plain stone, with no rune on it. The ladder that stood in front of it has left two grooves in the floor, a thousand years deep." },
    { name = "a silverfish",
      icon = "~",
      description = "On the oldest slab, the length of your finger, the colour of a new nail. It lives in the cut runes and eats the dust out of them. The clerks call it the junior reviewer and step round it.",
      actions = {
        { "Watch it work", say "It goes along one stroke of one rune, end to end, and leaves it clean. Then it stops, and seems to read it, and goes on to the next. You wonder what it makes of them." },
      } },
    { name = "the apologies desk",
      description = "A small counter at the far end, under the stair, with a clerk asleep behind it and a slate that says {i}OPEN{/}. A grudge may be withdrawn here, by the offender, in person, with a form. The inkwell is dry.",
      things = {
        { name = "the form", description = "One page. {i}I, ______, was in the wrong.{/} The stack of blanks is the height of a dwarf and yellow at the edges. The top one has a ring from a mug." },
        { name = "the clerk", description = "He has held the desk for a hundred and ten years. It is the best post in the Hall, he says: a stool, a lamp and no interruptions. He took it for the quiet. He had one caller, once, who wanted the privy." },
      },
      actions = {
        { "Fill in a form", say "You take one and think. There was the bed at the Griffon. You write it down. The clerk wakes, reads it, reads it again, and has to sit on his stool. He stamps it. It is the first withdrawal in the history of the Hall and it concerns a bed on the surface. It is filed, in a new drawer, made for the purpose, under your name." },
      } },
    { name = "the index lamp",
      description = "One lamp, on a chain, that travels along a rail above the shelves and is pulled by a cord to wherever it is wanted. There is one lamp for nine miles of grievance. The Keeper says that nobody has ever needed to look at two at once. A grudge wants your whole attention." },
  },

  exits = {
    { to = "plumb_square", description = "Down the nine steps, between the stacked stone ledgers." },
    { to = "unlodged", label = "The low door behind the index",
      description = "On your knees, through a door that has not been opened since they put it there.",
      requires = flag "fe_knows_unlodged", hidden = true },
  },
}

space {
  id = "unlodged",
  region = "far_enough",
  secret = true,
  name = "The Unlodged Room",
  description = "A small bare room behind the index, with one lamp. This is where the Hall keeps what it could not file. There is not much. A dwarf can put almost anything into words and then into stone. In the middle of the floor, on two trestles, lies the slab they brought up from the Longshift.",
  palette = { bg = "#0a0b10", text = "#c8ccd6", dim = "#5e6478", accent = "#8fa8f0", border = "#2e3658" },
  ambience = {
    dust { glyphs = "·", color = "#464a5c", rate = 0.1, speed = 0.1 },
    shimmer { color = "#8fa8f0", strength = 0.12 },
  },

  things = {
    { name = "the blank slab",
      key = "blank slab",
      wonder = true,
      icon = "▭",
      description = "Grey stone, six feet by three, dressed and polished for carving, with a border already cut. {magic}There is nothing on it.{/} Forty miners carried it here between them on the day down ran out, and stood with it at the counter, and could not say who had wronged them. It has waited a thousand years for the first stroke. The polish has been kept up.",
      things = {
        { name = "the border", description = "Cut that same day, on the walk up from the mine, by miners taking turns. It is a pattern of picks, laid head to handle, all the way round. One pick in it is smaller than the rest." },
        { name = "one chisel mark", description = "Top left, where a line of runes would begin: a single nick, a finger wide. Somebody started. You can see from the angle that it was going to be the rune for {i}against{/}, and you can see where the hand stopped." },
        { name = "the polish", description = "You can see the lamp in it, and yourself, and above you both a dark ceiling. For a moment the reflection of the ceiling seems very far up, and blue. It is the stone. It is a bluish stone." },
        { name = "forty thumbprints", description = "Along the two long edges, worn into the stone itself: where it was carried. They have never been polished out. The Keepers say that that part, at least, is a record." },
      },
      actions = {
        { "Think what you would carve", fx("wash", "#8fa8f0"),
          say "You have stood where they stood, and leaned out. You try it. {i}Against the sky, for being there.{/} No. {i}Against down, for stopping.{/} No. You stand at the slab for a long time, and at the end you have what they had, which is the wish to say something and nobody to say it to. You leave it blank. It seems to have been the right answer all along." },
        { "Touch it", say "Cool, and as smooth as water in a cup. Your fingers leave no mark. A thousand years of clerks have made sure that nothing does." },
      } },
    { name = "a shelf of replies",
      key = "reply shelf",
      description = "A stone shelf with a label: {i}ANSWERS RECEIVED{/}. It was put up at the founding, in a spirit of fairness, for anything said back by the accused. It holds one item.",
      variants = {
        { when = item "mountain_reply",
          description = "A stone shelf with a label: {i}ANSWERS RECEIVED{/}. It is empty, and in the dust there is the shape of an egg. Under the label somebody has already chalked: {i}on loan, to a tall person, who will see that it is heard{/}. You did not see anyone come in." },
      },
      things = {
        { name = "a grey stone", visible_if = no(item "mountain_reply"),
          description = "The size of a hen's egg, on a square of felt. A slate beside it: {i}Fell from the roof at the ninth review of the First Grudge, onto the Keeper's desk, at the moment the charge was read. Entered as the mountain's reply. Meaning: disputed. Forty opinions attached.{/}",
          actions = {
            { "Take the mountain's reply", once = true, give "mountain_reply",
              say "You lift it off the felt. It is far heavier than it should be, and you nearly drop it, and somewhere a long way overhead something settles, as a house does at night. {gold}The Mountain's Reply.{/} Nobody has known what to do with it for a hundred years. You do not know either. But you are going up, and out, and it has never been." },
          } },
        { name = "the forty opinions", description = "Forty slates, tied in a bundle. {i}It means sorry.{/} {i}It means no.{/} {i}It means the mountain was not listening and a stone fell.{/} The fortieth, in a child's hand: {i}it means it is heavy for the mountain too{/}. That one has been moved to the top." },
      } },
    { name = "a slab with one word",
      description = "Leaning in the corner. A grudge begun by a dwarf who came in furious, stood at the counter, and forgot what it was. One rune: {i}against{/}. He comes in every few years and looks at it, in case." },
    { name = "a slab in two halves",
      description = "Split down the middle, each half carved by a different hand. It is a single grudge, lodged by two brothers against each other, at the same moment, for the same thing, in the same words. The Hall could not decide which to file it under. They visit it together." },
    { name = "a sealed jar",
      description = "Clay, stoppered with wax, with a tile hung on it: {i}A grievance told to the Keeper in confidence and not to be carved until both parties are dead. One remains.{/} The wax is nine hundred years old.",
      actions = {
        { "Shake it", say "You do not. You pick it up, and find that you are not going to, and put it down again. There are some things even an adventurer does not rattle." },
      } },
    { name = "a child's slate",
      description = "Propped on the shelf below the replies. A grudge in chalk, with a drawing: a small dwarf, a large dwarf, a pudding. It was never carved, since the complainant made it up with the accused before supper. The Keeper of the day kept it. He was the accused." },
    { name = "the lamp",
      description = "One, of clear glass, trimmed daily, in a room nobody visits. A grievance that could not be lodged, the Keepers hold, is still owed a light.",
      things = {
        { name = "the oil", description = "Paid for out of the Keeper's own wage, by custom, since the Hall's accounts have no heading for it." },
      } },
    { name = "the inside of the low door",
      description = "On this side somebody has cut one line, at dwarf eye level, small. A clerk's hand, a thousand years old. You cannot read it. You get down and look anyway, and find that some later visitor has pencilled the meaning under it: {i}we did not know what to call it, so we kept it{/}." },
    { name = "the trestles",
      description = "Oak, from the surface, pegged, and built to carry the slab for as long as it took. Each foot stands in a stone cup of oil, to keep the damp from the wood. The cups are full." },
    { name = "a cave spider",
      icon = "x",
      description = "Pale, long in the leg, with a web across the upper corner that has been mended so many times it is thicker than cloth. The clerks who come to trim the lamp leave it be. It was here before the room was.",
      actions = {
        { "Blow gently on the web", say "It shivers, and the spider comes out to the middle and waits, and finds it was nothing, and goes back. You have been filed, here too." },
      } },
    { name = "a slab with a drawing",
      description = "No runes. A picture, scratched with a nail, of a dwarf and a much taller figure, hand in hand, and over both a round thing with lines coming off it. Whoever made it had heard of the sun and not seen it.",
      things = {
        { name = "the round thing", description = "It has a face. It is smiling. The Hall could not find a category. It is not a grudge. The Keeper says there was talk of starting a second hall for the other thing, and that the idea was let lie, since nobody could agree what the other thing was called." },
      } },
    { name = "the visitors' stool",
      description = "Three legs, one short, with a wedge under it cut to the thousandth. It is the only wobbling thing in Far Enough that has been corrected and not replaced. The Keeper says that it was hers.",
      actions = {
        { "Sit on it", say "It takes you, on its wedge, dead level. You sit in a bare room with one lamp, among the things a whole people could not find the words for, and for once you do not look for any either." },
      } },
  },

  exits = {
    { to = "grudge_hall", label = "The low door", description = "Out on your knees, to the sound of small chisels." },
  },
}
